INSERT INTO ums_role (name, description, admin_count, create_time, status, sort) VALUES ('SUPER_ADMIN', 'Full access to every module', 0, CURRENT_TIMESTAMP, 1, 99);
INSERT INTO ums_role (name, description, admin_count, create_time, status, sort) VALUES ('CATALOG_MANAGER', 'Maintains products, brands, stock and preorder windows', 0, CURRENT_TIMESTAMP, 1, 98);
INSERT INTO ums_role (name, description, admin_count, create_time, status, sort) VALUES ('ORDER_MANAGER', 'Handles orders, returns, personalisation requests and payments', 0, CURRENT_TIMESTAMP, 1, 97);
INSERT INTO ums_role (name, description, admin_count, create_time, status, sort) VALUES ('MARKETING_MANAGER', 'Runs coupons, home page slots and bundles', 0, CURRENT_TIMESTAMP, 1, 96);
INSERT INTO ums_role (name, description, admin_count, create_time, status, sort) VALUES ('CONTENT_EDITOR', 'Edits subjects, help articles, pairings and serving guides', 0, CURRENT_TIMESTAMP, 1, 95);
INSERT INTO ums_role (name, description, admin_count, create_time, status, sort) VALUES ('PRODUCTION_LEAD', 'Plans batches, releases stock and follows the launch playbook', 0, CURRENT_TIMESTAMP, 1, 94);
INSERT INTO ums_role_resource_relation (role_id, resource_id) SELECT r.id, s.id FROM ums_role r CROSS JOIN ums_resource s WHERE r.name = 'SUPER_ADMIN';
INSERT INTO ums_role_menu_relation (role_id, menu_id) SELECT r.id, m.id FROM ums_role r CROSS JOIN ums_menu m WHERE r.name = 'SUPER_ADMIN';
INSERT INTO ums_role_resource_relation (role_id, resource_id) SELECT r.id, s.id FROM ums_role r CROSS JOIN ums_resource s WHERE r.name = 'CATALOG_MANAGER' AND s.url IN ('/product/**', '/productCategory/**', '/brand/**', '/flavor/**', '/chocolateType/**', '/allergen/**', '/stock/**', '/preorderWindow/**', '/experience/**', '/bundle/**', '/file/**', '/report/**');
INSERT INTO ums_role_menu_relation (role_id, menu_id) SELECT r.id, m.id FROM ums_role r CROSS JOIN ums_menu m WHERE r.name = 'CATALOG_MANAGER' AND (m.name IN ('catalog', 'marketing') OR m.parent_id IN (SELECT id FROM ums_menu WHERE parent_id = 0 AND name IN ('catalog', 'marketing')));
INSERT INTO ums_role_resource_relation (role_id, resource_id) SELECT r.id, s.id FROM ums_role r CROSS JOIN ums_resource s WHERE r.name = 'ORDER_MANAGER' AND s.url IN ('/order/**', '/returnApply/**', '/returnReason/**', '/orderSetting/**', '/shopLocation/**', '/personalization/**', '/payment/**', '/member/**', '/memberLevel/**', '/report/**');
INSERT INTO ums_role_menu_relation (role_id, menu_id) SELECT r.id, m.id FROM ums_role r CROSS JOIN ums_menu m WHERE r.name = 'ORDER_MANAGER' AND (m.name IN ('sales', 'members') OR m.parent_id IN (SELECT id FROM ums_menu WHERE parent_id = 0 AND name IN ('sales', 'members')));
INSERT INTO ums_role_resource_relation (role_id, resource_id) SELECT r.id, s.id FROM ums_role r CROSS JOIN ums_resource s WHERE r.name = 'MARKETING_MANAGER' AND s.url IN ('/coupon/**', '/couponHistory/**', '/home/**', '/bundle/**', '/preorderWindow/**', '/experience/**', '/report/**', '/file/**');
INSERT INTO ums_role_menu_relation (role_id, menu_id) SELECT r.id, m.id FROM ums_role r CROSS JOIN ums_menu m WHERE r.name = 'MARKETING_MANAGER' AND (m.name IN ('marketing', 'reports') OR m.parent_id IN (SELECT id FROM ums_menu WHERE parent_id = 0 AND name IN ('marketing', 'reports')));
INSERT INTO ums_role_resource_relation (role_id, resource_id) SELECT r.id, s.id FROM ums_role r CROSS JOIN ums_resource s WHERE r.name = 'CONTENT_EDITOR' AND s.url IN ('/subject/**', '/help/**', '/pairing/**', '/serving/**', '/file/**');
INSERT INTO ums_role_menu_relation (role_id, menu_id) SELECT r.id, m.id FROM ums_role r CROSS JOIN ums_menu m WHERE r.name = 'CONTENT_EDITOR' AND (m.name IN ('content') OR m.parent_id IN (SELECT id FROM ums_menu WHERE parent_id = 0 AND name IN ('content')));
INSERT INTO ums_role_resource_relation (role_id, resource_id) SELECT r.id, s.id FROM ums_role r CROSS JOIN ums_resource s WHERE r.name = 'PRODUCTION_LEAD' AND s.url IN ('/production/**', '/guide/**', '/stock/**', '/product/**', '/allergen/**', '/report/**');
INSERT INTO ums_role_menu_relation (role_id, menu_id) SELECT r.id, m.id FROM ums_role r CROSS JOIN ums_menu m WHERE r.name = 'PRODUCTION_LEAD' AND (m.name IN ('operations', 'catalog') OR m.parent_id IN (SELECT id FROM ums_menu WHERE parent_id = 0 AND name IN ('operations', 'catalog')));
